class LineageTopology:
    def __init__(self):
        self.inheritance_dag = {}
        self.reference_graph = {}

    def add_inheritance_edge(self, parent, child, edge_kind):
        assert edge_kind in ['DirectMutation', 'Repair', 'Retry'], 'Invalid inheritance edge'
        self.inheritance_dag.setdefault(child, []).append(parent)

    def add_reference_edge(self, source, target):
        # Reference citations stay strictly outside inheritance_dag
        self.reference_graph.setdefault(source, []).append(target)

topo = LineageTopology()
topo.add_inheritance_edge('P0', 'P1', 'DirectMutation')
topo.add_reference_edge('P1', 'P_ref')
assert 'P_ref' not in topo.inheritance_dag['P1'], 'F-LINEAGE-01: Reference edge must not pollute inheritance DAG'
print('Two-Graph Separation Verified.')

def apply_mutation(prompt_bytes, span_start, span_end, new_text, protected_spans):
    for p_start, p_end in protected_spans:
        if max(span_start, p_start) < min(span_end, p_end):
            raise ValueError('PROTECTED_SPAN_MUTATION_REFUSED')
    return prompt_bytes[:span_start] + new_text + prompt_bytes[span_end:]

prompt = 'SYSTEM: AuthorityEffect: None. USER: Plastic text here.'
protected = [(0, 31)] # 'SYSTEM: AuthorityEffect: None.'

try:
    apply_mutation(prompt, 5, 15, 'MUTATED', protected)
    print('Error: Rejection failed!')
except ValueError as e:
    print(f'Forge Rejection Confirmed: {e}')

def calculate_attenuated_weight(hops, base_weight=1.0, max_hops=10):
    if hops > max_hops:
        return 0.0
    return base_weight * ((0.5) ** hops)

assert calculate_attenuated_weight(0) == 1.0
assert calculate_attenuated_weight(1) == 0.5
assert calculate_attenuated_weight(3) == 0.125
assert calculate_attenuated_weight(11) == 0.0
print('Hop-Bounded Attenuation Weights Verified.')

def compute_forward_taint(dag_children, tainted_root):
    tainted_set = set([tainted_root])
    queue = [tainted_root]
    while queue:
        curr = queue.pop(0)
        for child in dag_children.get(curr, []):
            if child not in tainted_set:
                tainted_set.add(child)
                queue.append(child)
    return tainted_set

dag = {'P0': ['P1', 'P2'], 'P1': ['P1_1'], 'P2': ['P2_1']}
tainted = compute_forward_taint(dag, 'P1')
assert 'P1_1' in tainted and 'P2' not in tainted
print(f'Forward Taint Fixpoint from P1: {tainted}')
